let res;
try {
  const v = require('lv-automation').verifyWebhooks;
  res = v.metaVerifyHandshake($json.query || {}, $env.META_VERIFY_TOKEN);
} catch (e) { res = { ok: false, reason: 'verifier_error', status: 403, body: 'Forbidden' }; }
return { json: { ok: res.ok === true, status: res.status || 403, body: res.body || 'Forbidden', reason: res.reason || '' } };

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  let ok = false;
  let reason = 'unverified';
  try {
    const raw = await this.helpers.getBinaryDataBuffer(i, 'data');
    const sig = (it.json.headers || {})['x-hub-signature-256'] || '';
    const v = require('lv-automation').verifyWebhooks;
    const res = v.verifyMetaSignature(raw, sig, $env.META_APP_SECRET);
    ok = !!(res && res.ok === true);
    reason = ok ? 'ok' : String((res && res.reason) || 'bad_signature');
  } catch (e) {
    reason = 'verifier_error: ' + String(e.message).slice(0, 80);
  }
  out.push({ json: { signature_ok: ok, reason: reason, body: it.json.body } });
}
return out;

// I-47g: W22 producer contract (automation/W22.md section 3). Handed to W22 by Execute Workflow smc-w22 (CONTRACTS.md
// "Sub-workflow interfaces": every call is Execute Workflow by id); no internal alert webhook.
return { json: { signal_key: 'webhook_signature_invalid', scope: 'webhook:W31', severity: 'red', what: 'W31 rejected a Meta messages webhook: ' + String($json.reason || 'unknown'), impact: 'A DM webhook call was refused; if Meta itself is misconfigured, real DMs are being missed', first_action: 'Check META_APP_SECRET and the messages subscription in the Meta app', source: 'W31' } };

const NL = String.fromCharCode(10);
const items = $input.all();
const raw = { rules: null, corpus: '', prompt: '', faq: '', guardrail: '' };
for (let i = 0; i < items.length; i++) {
  const b = items[i].binary && items[i].binary.data;
  if (!b) continue;
  const name = b.fileName || '';
  const txt = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8');
  if (name === 'rules.json') raw.rules = JSON.parse(txt);
  else if (name === 'reply-corpus.md') raw.corpus = txt;
  else if (name === 'classifier-prompt.md') raw.prompt = txt;
  else if (name === 'faq.md') raw.faq = txt;
  else if (name === 'guardrail.md') raw.guardrail = txt;
}
if (!raw.rules || !raw.corpus || !raw.prompt) throw new Error('community config files missing: rules, corpus or classifier prompt');
const a = raw.prompt.indexOf('---SYSTEM PROMPT START---');
const z = raw.prompt.indexOf('---SYSTEM PROMPT END---');
const system_prompt = raw.prompt.slice(a + 25, z).trim();
const corpus = {};
let facts = '';
let cur = null;
let inFacts = false;
for (const line of raw.corpus.split(NL)) {
  if (line.indexOf('#### ') === 0) {
    const p = line.slice(5).split('|');
    cur = { id: p[0].trim(), lang: (p[1] || 'en').trim() };
    corpus[cur.id] = corpus[cur.id] || {};
    corpus[cur.id][cur.lang] = corpus[cur.id][cur.lang] || [];
    inFacts = false;
    continue;
  }
  if (line.indexOf('## ') === 0) { cur = null; inFacts = line.indexOf('FAQ topics') >= 0; continue; }
  if (cur && line.indexOf('- ') === 0) corpus[cur.id][cur.lang].push(line.slice(2).trim());
  if (inFacts && line.charAt(0) === '|' && line.indexOf('---') < 0 && line.indexOf('| topic') !== 0) {
    const c = line.split('|').map((s) => s.trim()).filter(Boolean);
    if (c.length >= 2) facts += c[0] + ': ' + c[1] + NL;
  }
}
const cfg = { rules: raw.rules, system_prompt: system_prompt, corpus: corpus, facts: facts, faq: raw.faq, guardrail: raw.guardrail };
return [{ json: { cfg: cfg, payload: $('Verify signature').first().json.body } }];

const src = $input.first().json;
let p = src.payload || {};
if (p.body && !p.entry && p.body.entry) p = p.body;
const out = [];
const channel = p.object === 'instagram' ? 'instagram' : 'messenger';
for (const entry of (p.entry || [])) {
  for (const m of (entry.messaging || [])) {
    if (!m.sender || !m.sender.id) continue;
    if (String(m.sender.id) === String(entry.id)) continue;
    const msg = m.message || null;
    const pb = m.postback || null;
    if (msg && msg.is_echo) continue;
    if (!msg && !pb) continue;
    const qr = msg && msg.quick_reply && msg.quick_reply.payload;
    const text = (msg && msg.text) || (pb && (pb.title || pb.payload)) || '';
    if (!text && !qr) continue;
    out.push({ json: { channel: channel, owner_id: String(entry.id), sender_id: String(m.sender.id), text: text, payload: qr || (pb && pb.payload) || '', mid: (msg && msg.mid) || '', ts: m.timestamp } });
  }
}
return out;

const ev = $('Normalise DM events').item.json;
const convo = $json;
const cfg = $('Load config').first().json.cfg;
const D = cfg.rules.dm_rules;
const AP = String.fromCharCode(39);
const toks = (ev.text || '').toLowerCase().split('').map((c) => ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c === AP ? c : ' ')).join('').split(' ').filter(Boolean);
const norm = ' ' + toks.join(' ') + ' ';
const has = (p) => norm.indexOf(' ' + String(p).toLowerCase() + ' ') >= 0;
const state = convo.state || {};
let route = 'classify';
if (ev.mid && state.last_mid === ev.mid) route = 'dup';
else if (convo.opted_out === true) route = 'paused';
else if (has('stop') || has('unsubscribe') || has('opt out') || has('optout')) route = 'stop';
else if (convo.paused === true) route = 'paused';
else if (D.handoff_phrases_en.concat(D.handoff_phrases_af).some((p) => has(p)) || ev.payload === 'HANDOFF') route = 'handoff';
else if (state.step === 'asked_age' && (ev.text || '').indexOf('?') < 0) route = 'age_answer';
const afw = ['ek', 'jy', 'nie', 'dit', 'die', 'wat', 'kos', 'asseblief', 'dankie', 'hoe', 'lank', 'baie', 'vertrou', 'skelm', 'gesprek', 'bel', 'maand', 'wie', 'eintlik', 'vra', 'nog', 'het', 'sal', 'vir', 'maar', 'net', 'vraag', 'mens', 'persoon', AP + 'n'];
const lang = toks.filter((t) => afw.indexOf(t) >= 0).length >= 2 ? 'af' : 'en';
const red = (ev.text || '').replace(new RegExp('[0-9]{4,}', 'g'), '[digits]').slice(0, 600);
const userTurn = { surface: ev.channel === 'instagram' ? 'ig_dm' : 'messenger', text: red, parent_is_ad: false, is_nested_reply: false, prior_exchanges_with_person_on_post: 0 };
const classify_body = { model: 'claude-haiku-4-5-20251001', max_tokens: 60, temperature: 0, system: cfg.system_prompt, messages: [ { role: 'user', content: JSON.stringify(userTurn) } ] };
return { json: { route: route, lang: lang, text_redacted: red, classify_body: classify_body } };

const route = $('Route').item.json;
const r = $json || {};
let cls = null;
try {
  let t = ((r.content && r.content[0] && r.content[0].text) || '').trim();
  t = t.replace(/```json|```/g, '').trim();
  const o = JSON.parse(t);
  const ok = ['question', 'interest', 'objection', 'complaint', 'praise', 'spam', 'abuse', 'competitor', 'off_topic', 'sensitive', 'own_data_posted'];
  if (ok.indexOf(o.intent) >= 0 && typeof o.needs_human === 'boolean' && typeof o.fais_risk === 'boolean' && Object.keys(o).length === 3) cls = { intent: o.intent, needs_human: o.needs_human, fais_risk: o.fais_risk };
} catch (e) { cls = null; }
return { json: Object.assign({}, route, { classification: cls }) };

const r = $json;
const ev = $('Normalise DM events').item.json;
const convo = $('Upsert conversation').item.json;
const prof = $('Get profile').item.json || {};
const cfg = $('Load config').first().json.cfg;
const D = cfg.rules.dm_rules;
const AP = String.fromCharCode(39);
const lang = r.lang || 'en';
const first = prof.first_name ? String(prof.first_name) : (prof.name ? String(prof.name).split(' ')[0] : '');
const state = Object.assign({ step: 'new', faq_count: 0, cta_count: 0, disclosed: false }, convo.state || {});
const route = r.route;
const cls = r.classification || null;
const key0 = cls ? cls.intent : 'off_topic';
const nh = cls ? cls.needs_human === true : false;
const fais = cls ? cls.fais_risk === true : false;
const failClosed = route === 'classify' && !cls;
const pick = (id) => { const v = (cfg.corpus[id] && (cfg.corpus[id][lang] || cfg.corpus[id].en)) || []; if (!v.length) return ''; let s = 0; for (const ch of String(ev.sender_id)) s += ch.charCodeAt(0); return v[(s + state.faq_count + state.cta_count) % v.length]; };
const fill = (s) => { if (first) return s.split('{first_name}').join(first); const o = s.split(', {first_name}').join('').split(' {first_name}').join('').split('{first_name}, ').join('').split('{first_name}').join(''); return o.charAt(0).toUpperCase() + o.slice(1); };
const ref = state.origin_ref || ('dm_' + ev.channel);
const base = $env.CTWA_BASE_URL;
const link = base ? (base + '/' + ref) : ('https://sortmycover.co.za/?utm_source=meta&utm_medium=dm&utm_campaign=' + ref);
const withLink = (s) => fill(s.split('{ctwa_link}').join(link).split('{page_link}').join(link));
const prefix = state.disclosed ? '' : fill(pick('disclosure_line')) + ' ';
const sast = new Date(Date.now() + 7200000);
const mins = sast.getUTCHours() * 60 + sast.getUTCMinutes();
const inHours = mins >= 420 && mins < 1320;
const due = new Date(Date.UTC(sast.getUTCFullYear(), sast.getUTCMonth(), sast.getUTCDate() + (mins >= 1320 ? 1 : 0), 7, 15) - 7200000).toISOString();
let text = '';
let after = '';
let needDraft = false;
let ask = false;
let esc = null;
let pause = false;
const patch = {};
const human = (kind) => { pause = true; esc = { kind: kind, to: ['Jonathan', 'KG'], human_within_seconds: 1800 }; };
if (route === 'handoff' || failClosed || (nh && key0 !== 'own_data_posted')) {
  if (key0 === 'sensitive') { human('sensitive'); }
  else { text = prefix + fill(pick('dm_handoff')); human(route === 'handoff' ? 'dm_handoff' : (failClosed ? 'classifier_invalid' : (key0 === 'complaint' ? 'complaint' : 'needs_human'))); }
} else if (route === 'age_answer') {
  let band = 'unknown';
  const pl = ev.payload || '';
  if (pl === 'AGE_LT35') band = 'lt35'; else if (pl === 'AGE_35_44') band = '35_44'; else if (pl === 'AGE_45_50') band = '45_50'; else if (pl === 'AGE_51P') band = '51p';
  else {
    let num = '';
    for (const c of (ev.text || '')) { if (c >= '0' && c <= '9') num += c; else if (num) break; }
    const n = num ? parseInt(num, 10) : -1;
    if (n >= 18 && n < 35) band = 'lt35'; else if (n >= 35 && n <= 44) band = '35_44'; else if (n >= 45 && n <= 50) band = '45_50'; else if (n >= 51 && n < 120) band = '51p';
  }
  patch.age_band = band; patch.step = 'done'; patch.cta_count = state.cta_count + 1;
  text = prefix + withLink(pick('dm_cta'));
} else if (['spam', 'abuse', 'competitor'].indexOf(key0) >= 0) {
  text = '';
} else if (state.step === 'done') {
  if (['question', 'interest', 'objection'].indexOf(key0) >= 0 && !fais && state.cta_count < 2) { text = withLink(pick('dm_cta')); patch.cta_count = state.cta_count + 1; }
  else if (['question', 'interest', 'objection'].indexOf(key0) >= 0) { text = fill(pick('dm_handoff')); human('dm_after_link'); }
} else if (fais) {
  text = prefix + withLink(pick('dm_advice_deferral')); patch.step = 'done'; patch.cta_count = state.cta_count + 1;
} else if (key0 === 'question' || key0 === 'objection') {
  if (state.faq_count >= D.max_faq_answers_before_cta) { text = prefix + withLink(pick('dm_cta')); patch.step = 'done'; patch.cta_count = state.cta_count + 1; }
  else { needDraft = true; after = fill(pick('dm_qualifying_age')); ask = true; patch.step = 'asked_age'; patch.faq_count = state.faq_count + 1; }
} else if (key0 === 'interest' || key0 === 'own_data_posted') {
  text = prefix + fill(pick('dm_qualifying_age')); ask = true; patch.step = 'asked_age';
} else if (!state.disclosed) {
  text = fill(pick('dm_opener'));
}
if (text || needDraft) patch.disclosed = true;
const fallback = prefix + withLink(pick('dm_advice_deferral'));
const plan = { channel: ev.channel, owner_id: ev.owner_id, sender_id: ev.sender_id, route: route, key: key0, lang: lang, reply_text: text, prefix: prefix, after: after, fallback: fallback, ask: ask, esc: esc, pause: pause, patch: patch, state: state, in_hours: inHours, due_at: due, guardrail_trip: false };
return { json: { plan: plan, need_draft: needDraft, key: key0, cls: cls, text_redacted: r.text_redacted || '' } };

const d = $json;
const cfg = $('Load config').first().json.cfg;
const NL = String.fromCharCode(10);
const facts = cfg.faq ? cfg.faq : cfg.facts;
const lang = d.plan.lang === 'af' ? 'Afrikaans' : 'plain South African English';
const sys = 'You write ONE short private chat answer for SortMyCover on Messenger or Instagram. SortMyCover connects people with a licensed financial adviser for a 30-minute call. Rules: at most 2 sentences. Reading grade 5 to 7. Language: ' + lang + '. No exclamation marks. No emoji. No links. No numbers except 30. Never mention price, premium, rand amounts, insurers, products, cover amounts, comparisons or recommendations. Speak about the adviser and SortMyCover in the third person. Do not argue. Use only the FACTS below. If the facts do not answer the question, output exactly NO_ANSWER. Output only the answer text.' + NL + NL + 'FACTS:' + NL + String(facts).slice(0, 6000);
const body = { model: 'claude-haiku-4-5-20251001', max_tokens: 120, temperature: 0.2, system: sys, messages: [ { role: 'user', content: 'Type: ' + d.key + NL + 'Message: ' + d.text_redacted } ] };
return { json: Object.assign({}, d, { draft_body: body }) };

const cfg = $('Load config').first().json.cfg;
const NL = String.fromCharCode(10);
const r = $json || {};
const draft = ((r.content && r.content[0] && r.content[0].text) || '').trim();
const reasons = [];
if (!draft || draft.indexOf('NO_ANSWER') >= 0) reasons.push('no_answer');
if (draft.indexOf('!') >= 0) reasons.push('exclamation');
const low = draft.toLowerCase();
if (low.indexOf('http') >= 0 || low.indexOf('www.') >= 0 || low.indexOf('.co.za') >= 0 || low.indexOf('.com') >= 0) reasons.push('link');
const digits = draft.replace(new RegExp('[^0-9]', 'g'), '');
if (digits.length > 0 && digits !== '30') reasons.push('digits');
const banned = ['premium', 'price', 'rand', 'insurer', 'policy', 'policies', 'cover amount', 'how much cover', 'compare', 'comparison', 'cheapest', 'best cover', 'you should', 'guarantee', 'financial advice', 'appointment', 'discovery', 'sanlam', 'old mutual', 'liberty', 'momentum', 'outsurance', 'hollard', '1life', 'assupol', 'brightrock', 'tax', 'recommend', 'suits you', 'suitable'];
for (const b of banned) { if (low.indexOf(b) >= 0) reasons.push('banned:' + b); }
const sentences = draft.split('.').join('|').split('?').join('|').split('|').filter((s) => s.trim().length > 1).length;
if (sentences > 2) reasons.push('too_long');
const stub = 'You are the FAIS guardrail gate for chat replies by SortMyCover, a South African lead-generation service that is not a financial services provider. A reply FAILS if it mentions or implies any premium, price, rand amount, cover amount, product, insurer, comparison, suitability, tax treatment, recommendation, or uses the phrase you should. A reply PASSES only if it answers about the call or the company in the third person, or defers to the licensed adviser.';
const sys = (cfg.guardrail ? cfg.guardrail : stub) + NL + NL + 'Community gate mode: judge the DRAFT reply below. Output exactly PASS or FAIL and nothing else.';
let userTurn = '';
try {
  const dd = $('Decide DM').item.json;
  const gm = require('lv-automation').guardrail;
  userTurn = gm.classifierInput({ draft: draft, question: dd.text_redacted || '', lang: (dd.plan && dd.plan.lang) || 'en', surface: 'whatsapp' });
} catch (e) { reasons.push('classifier_input_unavailable'); }
const gate_body = { model: 'claude-haiku-4-5-20251001', max_tokens: 10, temperature: 0, system: sys, messages: [ { role: 'user', content: userTurn } ] };
return { json: { draft: draft, lint_ok: reasons.length === 0, reasons: reasons, gate_body: gate_body } };

const d = $('Decide DM').item.json;
const L = $('Lint draft').item.json;
const r = $json || {};
const gate = String((r.content && r.content[0] && r.content[0].text) || '').trim().toUpperCase();
const pass = L.lint_ok === true && gate.indexOf('PASS') === 0;
const plan = JSON.parse(JSON.stringify(d.plan));
if (pass) {
  plan.reply_text = plan.prefix + L.draft + ' ' + plan.after;
} else {
  plan.guardrail_trip = L.reasons.indexOf('no_answer') < 0;
  plan.reply_text = plan.fallback;
  plan.ask = false;
  plan.patch.step = 'done';
  plan.patch.cta_count = (plan.state.cta_count || 0) + 1;
}
return { json: Object.assign({}, d, { plan: plan }) };

const plan = $json.plan;
const ev = $('Normalise DM events').item.json;
const af = plan.lang === 'af';
const t = af ? ['Onder 35', '35 tot 44', '45 tot 50', '51 en ouer'] : ['Under 35', '35 to 44', '45 to 50', '51 and over'];
const pl = ['AGE_LT35', 'AGE_35_44', 'AGE_45_50', 'AGE_51P'];
const qr = plan.ask ? t.map((x, i) => ({ content_type: 'text', title: x, payload: pl[i] })) : [];
const newState = Object.assign({}, plan.state, plan.patch, { last_mid: ev.mid || plan.state.last_mid || '' });
const MAP = { sensitive: 'human_handoff', dm_handoff: 'dm', dm_after_link: 'dm' };
const esc = plan.esc ? Object.assign({}, plan.esc, { kind_requested: plan.esc.kind, kind_stored: ($env.ESC_REAL_KINDS === 'true') ? plan.esc.kind : (MAP[plan.esc.kind] || plan.esc.kind) }) : null;
const out = { channel: plan.channel, owner_id: plan.owner_id, sender_id: plan.sender_id, reply_text: plan.reply_text || '', quick_replies: qr, esc: esc, paused: plan.pause === true, new_state: newState, queue: !plan.in_hours && !!plan.reply_text, due_at: plan.due_at, window_expires_at: new Date(Date.now() + 86400000).toISOString(), key: plan.key, guardrail_trip: plan.guardrail_trip === true };
return { json: out };

// I-47g: W22 producer contract (automation/W22.md section 3). Handed to W22 by Execute Workflow smc-w22 (CONTRACTS.md
// "Sub-workflow interfaces": every call is Execute Workflow by id); no internal alert webhook.
const f = $('Finalise DM').item.json; const esc = f.esc || {};
const link = ($env.CONSOLE_URL || '') + '/community/escalations/' + $json.id;
return { json: { signal_key: 'community_escalation', scope: 'escalation:' + String($json.id || 'unknown'), severity: 'amber', what: 'Community DM on ' + f.channel + ': ' + esc.kind + '. The bot is paused. A person from the team needs to follow up.', impact: 'A person is waiting in a DM; the bot is paused', first_action: 'Open ' + link, deep_link: link, esc_kind: esc.kind, kind_requested: esc.kind_requested || esc.kind, recipients_hint: esc.to, source: 'W31' } };

if ($json.reply_text) return { json: $json };
const f = $('Finalise DM').item.json;
return { json: { queue_id: null, channel: f.channel, owner_id: f.owner_id, sender_id: f.sender_id, reply_text: f.reply_text, quick_replies: f.quick_replies, window_expires_at: f.window_expires_at } };

const p = $('Send ctx').item.json;
const r = $json || {};
const ok = !!(r && !r.error && (r.message_id || r.recipient_id));
return { json: { ok: ok, queue_id: p.queue_id || null, channel: p.channel, sender_id: p.sender_id, owner_id: p.owner_id, reply_text: p.reply_text, quick_replies: p.quick_replies || [], window_expires_at: p.window_expires_at } };

const out = [];
for (const it of $input.all()) {
  const b64 = String(it.json.raw_body_b64 || '');
  const buf = Buffer.from(b64, 'base64');
  let body = {};
  try { body = JSON.parse(buf.toString('utf8')); } catch (e) { body = {}; }
  const binary = { data: await this.helpers.prepareBinaryData(buf, 'raw.json', 'application/json') };
  out.push({ json: { headers: { 'x-hub-signature-256': String(it.json.signature || '') }, body }, binary });
}
return out;
